INSERT INTO "configuracao_global" ("id", "chave", "valor", "descricao", "pendente_confirmacao") VALUES (11, 'reducao_controle_capacidade_pct', 15.0, 'Redução MÁXIMA de consumo do compressor por Controle de Capacidade (descarregamento mecânico de cilindros — Modo Operação), aplicada quando o Sistema opera no piso de 35% de carga — decresce linearmente até 0% em 100% de carga. Faixa típica de literatura (descarregamento mecânico vs. liga-desliga): 15%-20% — ver calculo_consumo.py', FALSE);
INSERT INTO "configuracao_global" ("id", "chave", "valor", "descricao", "pendente_confirmacao") VALUES (12, 'reducao_inversor_pct', 30.0, 'Redução MÁXIMA de consumo do compressor por Inversor de Frequência (VFD — Modo Operação), aplicada quando o Sistema opera no piso de 20% de carga — decresce linearmente até 0% em 100% de carga. Faixa típica de literatura (VFD vs. liga-desliga, ganho de IEER): 30%-50% — ver calculo_consumo.py', FALSE);
INSERT INTO "configuracao_global" ("id", "chave", "valor", "descricao", "pendente_confirmacao") VALUES (13, 'reducao_ec_condensador_pct', 30.0, 'Redução MÁXIMA de consumo do ventilador do Condensador Remoto (Rack Paralelo, Tela 6) quando o modelo escolhido tem motor EC, aplicada quando o condensador opera no piso de 20% de carga (mesma folga de referência do Inversor de Frequência, tecnologia equivalente) — decresce linearmente até 0% em 100% de carga. Faixa típica de literatura (EC vs. motor AC de rotação fixa, ventiladores de condensador): 30%-50% — ver calculo_consumo.py', FALSE);
INSERT INTO "configuracao_global" ("id", "chave", "valor", "descricao", "pendente_confirmacao") VALUES (14, 'disjuntor_limite_curva_c_a', 80.0, 'Corrente nominal (A) até a qual o disjuntor usa Curva C — acima disso, Curva D (Tela 5 - Tabela de Disjuntores). Do cabeçalho da planilha original.', FALSE);
